@dataclass
class Backend:
    "Where a job runs"
    @property
    def name(self) -> str: return type(self).__name__.lower()

@dataclass
class Local(Backend):
    "A background process on this machine, in this environment; at most `max_jobs` at once"
    max_jobs:int = 1

@dataclass
class Colab(Backend):
    "A Colab VM through the `colab` CLI; `secrets` names the environment variables passed to it (the Hub token, for pushing)"
    auth:str = "oauth2"
    keep:bool = False
    secrets:tuple = ("HF_TOKEN",)

@dataclass
class Kaggle(Backend):
    "A Kaggle kernel through the `kaggle` CLI, under `owner` (the logged-in account by default)"
    owner:str|None = None
    private:bool = True
    internet:bool = True

@dataclass
class Modal(Backend):
    "A Modal sandbox, with the job's files on the Modal Volume `volume`, `cpu` cores and `memory_gb` beside any GPU; `secrets` names the environment variables passed to it (the Hub token); a job runs `max_hours` unless told otherwise, and with `budget` (dollars) none starts that could take the month's usage past it"
    app:str = "sysone"
    volume:str = "sysone-jobs"
    python:str = "3.12"
    image:str|None = None
    cpu:float = 2.0
    memory_gb:float = 8.0
    secrets:tuple = ("HF_TOKEN",)
    max_hours:float|None = 2.0
    budget:float|None = None

@dataclass
class SageMaker(Backend):
    "A SageMaker training job; `endpoint_url` points at an emulator such as floci, `local=True` uses the SDK's local mode"
    role:str|None = None
    bucket:str|None = None
    region:str|None = None
    endpoint_url:str|None = None
    image:str|None = None
    local:bool = False

BACKENDS = {"local": Local, "colab": Colab, "kaggle": Kaggle, "modal": Modal, "sagemaker": SageMaker}
BACKEND_MODULES = {"colab": "sysone.colab", "kaggle": "sysone.kaggle", "modal": "sysone.modal", "sagemaker": "sysone.aws"}

def backend(spec, **kw) -> Backend:
    "A backend from its name (`local`, `colab`, `kaggle`, `modal`, `sagemaker`) and settings, or the backend itself"
    if isinstance(spec, Backend): return spec
    if str(spec).lower() not in BACKENDS: raise ValueError(f"unknown backend {spec!r}; one of {sorted(BACKENDS)}")
    return BACKENDS[str(spec).lower()](**kw)

def load_backend(b:Backend) -> bool:
    "Import the module that holds a backend's methods; True if it was not loaded yet"
    mod = BACKEND_MODULES.get(b.name)
    if mod is None or mod in sys.modules: return False
    import importlib
    importlib.import_module(mod)
    return True

